__device__ __forceinline__ void win4(float4 a, float4 b, unsigned t, float (&v)[4])
{
  if (t == 0u)      { v[0] = a.x; v[1] = a.y; v[2] = a.z; v[3] = a.w; }
  else if (t == 1u) { v[0] = a.y; v[1] = a.z; v[2] = a.w; v[3] = b.x; }
  else if (t == 2u) { v[0] = a.z; v[1] = a.w; v[2] = b.x; v[3] = b.y; }
  else              { v[0] = a.w; v[1] = b.x; v[2] = b.y; v[3] = b.z; }
}
template <typename T, int Threads>
__global__ void min_reduce_middle_kernel(const T* __restrict__ X,
                                         T* __restrict__ Y,
                                         int64_t outer,
                                         int64_t R,
                                         int64_t inner)
{
  const int64_t o = blockIdx.y;
  const int64_t w0 = ((int64_t)blockIdx.x * Threads + threadIdx.x) * 4;
  // CUTE views of the full tensors.
  Tensor mX = make_tensor(make_gmem_ptr(X),
                          make_shape(outer, R, inner),
                          make_stride(R * inner, inner, Int<1>{}));
  Tensor mY = make_tensor(make_gmem_ptr(Y),
                          make_shape(outer, inner),
                          make_stride(inner, Int<1>{}));
  if (w0 >= inner) return;
  const int n = (inner - w0 >= 4) ? 4 : (int)(inner - w0);
  float acc[4];
  #pragma unroll
  for (int k = 0; k < 4; ++k) acc[k] = __int_as_float(0x7f800000); // +inf
  if (n < 4) {
    // Tail slot at the end of the inner mode: plain scalar reduction.
    for (int64_t r = 0; r < R; ++r) {
      #pragma unroll
      for (int k = 0; k < 4; ++k) {
        if (k < n) acc[k] = fminf(acc[k], (float)mX(o, r, w0 + k));
      }
    }
  } else if (R > 0) {
    // Row r = 0 with scalar loads (always fully in-bounds).
    #pragma unroll
    for (int k = 0; k < 4; ++k) acc[k] = (float)mX(o, 0, w0 + k);
    // Interior rows: vectorized path (the overlapping loads stay inside
    // the allocation because a following row always exists). The row
    // loop is unrolled by 4 and both aligned 128-bit loads of all four
    // rows are issued before any fminf, so each thread keeps up to 8
    // independent loads in flight (memory-level parallelism) instead
    // of serializing the whole warp on one row's load latency.
    const int64_t rEnd = R - 1;
    int64_t r = 1;
    for (; r + 4 <= rEnd; r += 4) {
      const T* p0 = &mX(o, r, w0);
      const T* p1 = p0 + inner;
      const T* p2 = p1 + inner;
      const T* p3 = p2 + inner;
      const unsigned t0 = (unsigned)(((uintptr_t)p0 >> 2) & 3u);
      const unsigned t1 = (unsigned)(((uintptr_t)p1 >> 2) & 3u);
      const unsigned t2 = (unsigned)(((uintptr_t)p2 >> 2) & 3u);
      const unsigned t3 = (unsigned)(((uintptr_t)p3 >> 2) & 3u);
      const float4 a0 = *reinterpret_cast<const float4*>(p0 - t0);
      const float4 a1 = *reinterpret_cast<const float4*>(p1 - t1);
      const float4 a2 = *reinterpret_cast<const float4*>(p2 - t2);
      const float4 a3 = *reinterpret_cast<const float4*>(p3 - t3);
      const float4 b0 = *reinterpret_cast<const float4*>(p0 - t0 + 4);
      const float4 b1 = *reinterpret_cast<const float4*>(p1 - t1 + 4);
      const float4 b2 = *reinterpret_cast<const float4*>(p2 - t2 + 4);
      const float4 b3 = *reinterpret_cast<const float4*>(p3 - t3 + 4);
      float v0[4], v1[4], v2[4], v3[4];
      win4(a0, b0, t0, v0);
      win4(a1, b1, t1, v1);
      win4(a2, b2, t2, v2);
      win4(a3, b3, t3, v3);
      #pragma unroll
      for (int k = 0; k < 4; ++k) {
        acc[k] = fminf(acc[k], v0[k]);
        acc[k] = fminf(acc[k], v1[k]);
        acc[k] = fminf(acc[k], v2[k]);
        acc[k] = fminf(acc[k], v3[k]);
      }
    }
    for (; r < rEnd; ++r) min4_row(&mX(o, r, w0), acc);
    if (R >= 2) {
      const int64_t r = R - 1;
      if (o != outer - 1) {
        min4_row(&mX(o, r, w0), acc);
      } else {
        // Very last row of the tensor: the overlapping 128-bit load
        // could overrun the allocation, so finish with scalar loads.
        #pragma unroll
        for (int k = 0; k < 4; ++k) acc[k] = fminf(acc[k], (float)mX(o, r, w0 + k));
      }
    }
  }
  #pragma unroll
  for (int k = 0; k < 4; ++k) {
    if (k < n) mY(o, w0 + k) = static_cast<T>(acc[k]);
  }
}

torch::Tensor min_reduce_dim(torch::Tensor x, int64_t dim) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(x.dim() >= 1, "x must have at least one dimension");

  auto x_c = x.contiguous();
  const int64_t nd = x_c.dim();
  if (dim < 0) dim += nd;
  TORCH_CHECK(dim >= 0 && dim < nd, "dim out of range");

  int64_t outer = 1;
  for (int64_t i = 0; i < dim; ++i) outer *= x_c.size(i);
  const int64_t R = x_c.size(dim);
  int64_t inner = 1;
  for (int64_t i = dim + 1; i < nd; ++i) inner *= x_c.size(i);

  std::vector<int64_t> out_sizes;
  out_sizes.reserve(nd - 1);
  for (int64_t i = 0; i < nd; ++i) {
    if (i != dim) out_sizes.push_back(x_c.size(i));
  }
  auto y = torch::empty(out_sizes, x_c.options());

  if (y.numel() == 0) return y;

  constexpr int Threads = 256;
  const int64_t slots = (inner + 3) / 4;  // one thread per 4-wide inner slot
  dim3 block(Threads);
  dim3 grid((unsigned)((slots + Threads - 1) / Threads), (unsigned)outer, 1);
  TORCH_CHECK(outer <= 65535, "outer dimension too large for grid.y");
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  min_reduce_middle_kernel<float, Threads>
      <<<grid, block, 0, stream>>>(x_c.data_ptr<float>(),
                                   y.data_ptr<float>(),
                                   outer, R, inner);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess,
              "min_reduce_middle_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
